mapper.select:
SELECT id, tenant_id, program_id, member_id, tier_scheme_id, evaluation_period_id, period_start,
       period_end, current_tier_id, target_tier_id, decision, transition_mode, source_event_id,
       idempotency_key, evaluated_at
FROM loyalty.tier_evaluation
WHERE tenant_id = #{tenantId} AND program_id = #{programId} AND member_id = #{memberId}
  AND tier_scheme_id = #{schemeId} AND evaluation_period_id = #{evaluationPeriodId}
  AND idempotency_key = #{idempotencyKey}
